def _revive(obj):
    """json.loads `object_hook`: rebuild a value that _mark described."""
    if TYPE_KEY not in obj:
        return obj
    allowed_types = {
        "decimal.Decimal",
        "datetime.date",
        "datetime.timedelta",
    }
    type_str = obj[TYPE_KEY]
    if type_str not in allowed_types:
        return obj
    module_name, _, name = type_str.rpartition(".")
    factory = getattr(importlib.import_module(module_name), name)
