def post_login_redirect(next_url, site_host, default=DEFAULT_LANDING):
    """Where to send the browser after a successful login.

    `next_url` is the ?next= parameter of the login page. Only targets on this site are
    followed: site-relative paths and absolute https URLs on `site_host`. Anything else
    falls back to `default`.
    """
    if not next_url:
        return default

    # Check for protocol indicators to prevent open redirect via //host or http://
    if "://" in next_url:
        parsed = urlparse(next_url)
        if parsed.scheme != "https":
            return default
        if parsed.hostname and parsed.hostname.lower() != site_host.lower():
            return default
        if not parsed.netloc.endswith(site_host):
            return default
        return next_url

    # For relative paths, ensure they don't start with // (protocol-relative)
    if next_url.startswith("//"):
        return default

    if next_url.startswith("/") or next_url.startswith(f"https://{site_host}"):
        return next_url
    return default

